(()=>{const menu=document.getElementById('menu'),toggle=document.getElementById('menu-toggle');let overflow='';function close(){menu.close();toggle.setAttribute('aria-expanded','false');document.body.style.overflow=overflow;toggle.focus()}toggle.addEventListener('click',()=>{overflow=document.body.style.overflow;menu.showModal();document.body.style.overflow='hidden';toggle.setAttribute('aria-expanded','true')});document.getElementById('menu-close').onclick=close;menu.addEventListener('cancel',e=>{e.preventDefault();close()});menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{menu.close();document.body.style.overflow=overflow}));const line=document.querySelector('.reading-line');let raf=0;function update(){raf=0;const range=document.documentElement.scrollHeight-innerHeight;line.style.transform=`scaleX(${range>0?Math.max(0,Math.min(1,scrollY/range)):0})`}addEventListener('scroll',()=>{if(!raf)raf=requestAnimationFrame(update)},{passive:true});addEventListener('resize',update,{passive:true});update()})();
